from pathlib import Path
import gzip,json,hashlib,subprocess
import numpy as np,pandas as pd
R=Path(__file__).resolve().parent
sig=pd.read_csv('/workspace/codex/results/PGAM5_state_adjustment_v3/EXPLORATORY_30_gene_macrophage_program_NOT_VALIDATED.csv');genes=sig.gene.tolist();assert len(genes)==30 and len(set(genes))==30
protocol={'task':'Exploratory TCGA-LIHC survival association using the supplied 30 candidate genes, despite failed earlier PGAM5 specificity validation','expression_source':'GSE62944/GSM1536837 TCGA24 tumor Rsubread FeatureCounts (2015 mirror), not current GDC STAR counts. LIHC identified using GEO cancer-type table; primary tumor sample type01 only','clinical_join':'Mirror includes normal/recurrent sample aliases of patient outcomes; verify duplicates agree across all8 endpoints, retain primary01 alias and join one-to-one by patient',
 'survival_source':'UCSCXenaShiny tcga_surv.rda mirror of Xena Toil TCGA_survival_data, attributed in source script to Liu et al Cell2018 doi10.1016/j.cell.2018.02.052; repository commit saved. OS and PFI in days. PFI is not PFS','sample_selection':'One primary-tumor RNA aliquot per 12-character patient ID, highest whole-matrix assigned gene count total then lexicographic barcode, outcome blind','score':'CPM=counts/sum(all gene counts)*1e6; log2(CPM+1); per-gene z scores using all unique primary LIHC patients (sampleSD ddof1), equal-weight mean over exactly30 genes. Not single-cell training z coefficients, deconvolution, or validated PGAM5-specific macrophage state. All30 required, missing/zero-variance gene stops analysis','grouping':'Global cohort median score, High>median, Low<=median; same fixed threshold for OS and PFI. No outcome-optimized cutpoint','endpoints':'OS=OS.time/OS; PFI=PFI.time/PFI. Include nonmissing binary event and finite time>0. Report exclusions separately. Do not rename PFI to PFS','statistics':'KM with Greenwood log-log95%CI, censor marks and risk tables; two-sided unweighted logrank; high-vs-low univariate Cox HR95%CI; BH over two primary logrank p values. No covariate-adjusted causal claim','limitations':'Exploratory candidate program not validated for PGAM5-specific state or macrophage abundance; stage/purity and other confounding unadjusted; no independent survival cohort; PFS unavailable'}
(R/'protocol.json').write_text(json.dumps(protocol,indent=2));sig.to_csv(R/'signature_30_genes.csv',index=False)
with gzip.open(R/'cancer_types.txt.gz','rt') as f:types=pd.read_csv(f,sep='\t',header=None,names=['sample','cancer_type'])
assert types['sample'].is_unique;wanted=types.loc[types.cancer_type.eq('LIHC'),'sample'].tolist();print('LIHC samples in metadata',len(wanted),flush=True)
lib=None;selected={};fullrows=0
with gzip.open(R/'TCGA24_tumor_featurecounts.txt.gz','rt') as f:
 header=f.readline().rstrip('\r\n').split('\t')[1:];assert len(header)==len(set(header));ix=pd.Index(header).get_indexer(wanted);assert (ix>=0).all();lib=np.zeros(len(ix),dtype=np.float64)
 for line in f:
  gene,sep,values=line.rstrip('\r\n').partition('\t');assert sep;v=np.fromstring(values,sep='\t',dtype=np.float64);assert len(v)==len(header) and np.isfinite(v).all() and (v>=0).all();vv=v[ix];lib+=vv;fullrows+=1
  if gene in genes+['PGAM5']:
   assert gene not in selected;selected[gene]=vv.copy()
  if fullrows%5000==0:print('Parsed gene rows',fullrows,flush=True)
assert set(genes+['PGAM5'])<=set(selected);assert (lib>0).all()
raw=pd.DataFrame(selected,index=wanted);info=pd.DataFrame({'sample':wanted,'patient':[s[:12] for s in wanted],'sample_type':[s[13:15] for s in wanted],'assigned_gene_counts':lib});info['primary_tumor']=info.sample_type.eq('01');info['selected']=False
keep=info[info.primary_tumor].sort_values(['patient','assigned_gene_counts','sample'],ascending=[True,False,True]).drop_duplicates('patient');info.loc[keep.index,'selected']=True;info.to_csv(R/'RNA_aliquot_selection.csv',index=False);raw.to_csv(R/'LIHC_all_aliquot_31_gene_counts.csv');assert keep.patient.is_unique
counts=raw.loc[keep['sample']];counts.index=keep.patient.to_numpy();den=keep.assigned_gene_counts.to_numpy();cpm=counts.div(den,axis=0)*1e6;log=np.log2(cpm+1);mean=log[genes].mean();sd=log[genes].std(ddof=1);assert (sd>0).all();z=(log[genes]-mean)/sd;score=z.mean(axis=1);cut=float(score.median());bulk=pd.DataFrame({'patient':counts.index,'RNA_sample':keep['sample'].to_numpy(),'candidate30_score':score.to_numpy(),'group':np.where(score.to_numpy()>cut,'High','Low'),'PGAM5_log2_CPM_plus1':log.PGAM5.to_numpy(),'assigned_gene_counts':den});bulk.to_csv(R/'patient_scores.csv',index=False);counts.to_csv(R/'selected_patient_31_gene_counts.csv');log.to_csv(R/'selected_patient_log2_CPM_plus1.csv');z.to_csv(R/'selected_patient_30_gene_zscores.csv');pd.DataFrame({'gene':genes,'bulk_training_mean_log2_CPM_plus1':mean.loc[genes].to_numpy(),'bulk_training_SD':sd.loc[genes].to_numpy(),'weight':1/30}).to_csv(R/'bulk_score_parameters.csv',index=False)
surv=pd.read_csv(R/'TCGA_CDR_mirror_survival.csv.gz');surv['patient']=surv['sample'].str[:12];s=surv[surv.patient.isin(bulk.patient)].copy();cols=['OS','OS.time','DSS','DSS.time','DFI','DFI.time','PFI','PFI.time'];assert s.groupby('patient')[cols].nunique(dropna=False).le(1).all().all();s.to_csv(R/'clinical_sample_duplicates_audit.csv',index=False);s=s[s['sample'].str[13:15].eq('01')].copy();assert s.patient.is_unique;merged=bulk.merge(s,on='patient',how='left',validate='one_to_one',indicator=True);merged.to_csv(R/'patient_scores_survival_join.csv',index=False)
summary={'GEO_gene_rows':fullrows,'GEO_all_tumor_RNA_aliquots':len(header),'LIHC_RNA_aliquots':len(wanted),'LIHC_primary_aliquots':int(info.primary_tumor.sum()),'unique_primary_patients':len(bulk),'30_signature_genes_present':True,'score_median':cut,'high_patients':int(bulk.group.eq('High').sum()),'low_patients':int(bulk.group.eq('Low').sum()),'survival_matched':int(merged['_merge'].eq('both').sum()),'survival_unmatched':int(merged['_merge'].eq('left_only').sum())};(R/'preparation_summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2),flush=True)
